package io.github.diodeme.ji.host;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.github.diodeme.ji.ai.Content;
import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiError;
import io.github.diodeme.ji.error.JiException;
import io.github.diodeme.ji.session.model.CanonicalSessionState;
import io.github.diodeme.ji.session.tree.SessionDocument;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.OptionalLong;
import java.util.function.UnaryOperator;

/** In-process reference HostStore with one canonical SessionDocument per Session. */
public final class MemoryHostStore implements HostStore {
    private final ObjectMapper mapper = new ObjectMapper();
    private final Map<String, State> sessions = new LinkedHashMap<>();

    @Override
    public synchronized SessionDocument create(
            String sessionId, ModelRef model, String workingDirectory, Instant createdAt) {
        if (sessions.containsKey(sessionId)) throw new IllegalStateException("session already exists: " + sessionId);
        SessionDocument document = SessionDocument.empty(sessionId, model, workingDirectory, createdAt);
        State state = new State();
        state.document = document;
        sessions.put(sessionId, state);
        return document;
    }

    @Override
    public synchronized Optional<SessionDocument> load(String sessionId) {
        State state = sessions.get(sessionId);
        return state == null ? Optional.empty() : Optional.of(state.document);
    }

    @Override
    public synchronized List<SessionDocument.Metadata> list() {
        return sessions.values().stream().map(state -> state.document.metadata()).toList();
    }

    @Override
    public synchronized SessionDocument update(
            String sessionId, long expectedRevision, UnaryOperator<SessionDocument> transition) {
        State state = requireSession(sessionId, expectedRevision);
        SessionDocument before = state.document;
        SessionDocument after = transition.apply(before);
        requireSuccessor(before, after);

        TerminalRun terminal = terminalRun(before, after).orElse(null);
        Journal journal = terminal == null ? null : state.commands.values().stream()
                .filter(candidate -> candidate.resultRef.equals(terminal.runId())
                        && candidate.status == Status.RESERVED && candidate.commit == null)
                .findFirst().orElse(null);

        byte[] encoded = null;
        long nextEventSeq = state.eventSeq;
        long nextSnapshotRevision = state.snapshotRevision;
        DurableEvent durable = null;
        Commit commit = null;
        if (journal != null) {
            encoded = encode(after, terminal.runId(), terminal.outcome());
            nextEventSeq = Math.incrementExact(state.eventSeq);
            nextSnapshotRevision = Math.incrementExact(state.snapshotRevision);
            durable = new DurableEvent(nextEventSeq, nextSnapshotRevision, "session.snapshot", encoded);
            commit = new Commit(journal.acceptedSeq, nextEventSeq, nextSnapshotRevision, terminal.runId());
        }

        state.document = after;
        if (journal != null) {
            state.eventSeq = nextEventSeq;
            state.snapshotRevision = nextSnapshotRevision;
            state.events.add(durable);
            state.snapshotPayload = encoded;
            state.snapshotBaseEventSeq = nextEventSeq;
            Journal completed = journal.completed(commit);
            state.commands.replaceAll((ignored, candidate) -> candidate == journal ? completed : candidate);
        }
        return after;
    }

    @Override
    public synchronized SessionDocument fork(
            String sourceSessionId, String newSessionId, String lane, Optional<String> targetEntryId,
            SessionDocument.ForkPosition position, Instant createdAt, long expectedSourceRevision) {
        if (sessions.containsKey(newSessionId)) throw new IllegalStateException("session already exists: " + newSessionId);
        State source = requireSession(sourceSessionId, expectedSourceRevision);
        SessionDocument fork = source.document.fork(newSessionId, lane, targetEntryId, position, createdAt);
        State state = new State();
        state.document = fork;
        sessions.put(newSessionId, state);
        return fork;
    }

    @Override
    public synchronized void delete(String sessionId, long expectedRevision) {
        State state = sessions.get(sessionId);
        if (state == null) return;
        if (state.document.revision() != expectedRevision) throw revisionConflict(expectedRevision, state.document.revision());
        sessions.remove(sessionId);
    }

    @Override
    public synchronized Reservation reserve(String sessionId, String commandId, String payloadHash,
                                            String resultRef, long expectedSessionRevision) {
        State state = requireSession(sessionId, expectedSessionRevision);
        Journal prior = state.commands.get(commandId);
        if (prior != null) {
            requireSamePayload(commandId, payloadHash, prior);
            if (prior.status == Status.RETRYABLE) {
                Journal reserved = prior.reserved();
                state.commands.put(commandId, reserved);
                return new Reservation(reserved.acceptedSeq, reserved.resultRef, reserved.status);
            }
            return new Reservation(prior.acceptedSeq, prior.resultRef, prior.status);
        }
        long acceptedSeq = Math.incrementExact(state.acceptedSeq);
        state.acceptedSeq = acceptedSeq;
        state.commands.put(commandId, new Journal(payloadHash, resultRef, acceptedSeq, Status.RESERVED, null));
        return new Reservation(acceptedSeq, resultRef, Status.RESERVED);
    }

    @Override
    public synchronized void release(String sessionId, String commandId, String payloadHash, String resultRef) {
        State state = sessions.get(sessionId);
        if (state == null) return;
        Journal journal = state.commands.get(commandId);
        if (journal == null) return;
        requireSamePayload(commandId, payloadHash, journal);
        if (!journal.resultRef.equals(resultRef)) throw new IllegalStateException("command.result_conflict");
        if (journal.commit != null) throw new IllegalStateException("command.already_completed");
        state.commands.put(commandId, journal.retryable());
    }

    @Override
    public synchronized Optional<CommandRecord> command(String sessionId, String commandId, String payloadHash) {
        State state = sessions.get(sessionId);
        if (state == null || !state.commands.containsKey(commandId)) return Optional.empty();
        Journal journal = state.commands.get(commandId);
        requireSamePayload(commandId, payloadHash, journal);
        return Optional.of(new CommandRecord(journal.acceptedSeq, journal.resultRef,
                journal.status, Optional.ofNullable(journal.commit)));
    }

    @Override
    public synchronized Snapshot snapshot(String sessionId) {
        State state = sessions.get(sessionId);
        if (state == null) return new Snapshot(0, 0, new byte[0]);
        return new Snapshot(state.snapshotRevision, state.snapshotBaseEventSeq, state.snapshotPayload);
    }

    @Override
    public synchronized List<DurableEvent> replay(String sessionId, long afterEventSeq) {
        if (afterEventSeq < 0) throw new IllegalArgumentException("afterEventSeq must be non-negative");
        State state = sessions.get(sessionId);
        if (state == null) return List.of();
        return state.events.stream().filter(event -> event.eventSeq() > afterEventSeq).toList();
    }

    private byte[] encode(SessionDocument document, String runId, String outcome) {
        var snapshot = document.snapshot();
        Map<String, Object> value = new LinkedHashMap<>();
        value.put("schemaVersion", 1);
        value.put("sessionId", snapshot.sessionId());
        value.put("sessionRevision", snapshot.revision());
        value.put("runId", runId);
        value.put("outcome", outcome);
        value.put("usage", Map.of(
                "inputTokens", snapshot.usage().inputTokens(),
                "outputTokens", snapshot.usage().outputTokens(),
                "cacheReadTokens", snapshot.usage().cacheReadTokens(),
                "cacheWriteTokens", snapshot.usage().cacheWriteTokens(),
                "costMicros", snapshot.usage().costMicros()));
        value.put("transcript", snapshot.transcript().stream().map(MemoryHostStore::message).toList());
        try {
            return mapper.writeValueAsBytes(value);
        } catch (JsonProcessingException exception) {
            throw new IllegalStateException("canonical Session document is not serializable", exception);
        }
    }

    private static Map<String, Object> message(Message message) {
        Map<String, Object> value = new LinkedHashMap<>();
        value.put("id", message.id());
        value.put("role", message.role().name().toLowerCase());
        value.put("text", message.text());
        message.toolCallId().ifPresent(id -> value.put("toolCallId", id));
        value.put("toolCalls", message.content().stream()
                .filter(Content.ToolCall.class::isInstance)
                .map(Content.ToolCall.class::cast)
                .map(call -> Map.<String, Object>of(
                        "id", call.id(), "name", call.name(), "arguments", call.arguments()))
                .toList());
        return value;
    }

    private State requireSession(String sessionId, long expectedRevision) {
        State state = sessions.get(sessionId);
        if (state == null || state.document == null) throw new IllegalStateException("session not found: " + sessionId);
        if (state.document.revision() != expectedRevision) {
            throw revisionConflict(expectedRevision, state.document.revision());
        }
        return state;
    }

    private static void requireSuccessor(SessionDocument current, SessionDocument next) {
        if (next == null || !next.metadata().sessionId().equals(current.metadata().sessionId())
                || next.revision() != Math.incrementExact(current.revision())) {
            throw new IllegalStateException("Session transition must preserve identity and advance revision once");
        }
    }

    private static Optional<TerminalRun> terminalRun(SessionDocument before, SessionDocument after) {
        Optional<CanonicalSessionState.Run> active = before.execution().activeRun();
        if (active.isEmpty() || after.execution().activeRun().isPresent()) return Optional.empty();
        String runId = active.orElseThrow().id().value();
        return after.execution().completedRuns().stream()
                .filter(run -> run.id().value().equals(runId))
                .findFirst()
                .map(run -> new TerminalRun(runId, run.outcome().orElseThrow().name().toLowerCase()));
    }

    private static IllegalStateException revisionConflict(long expected, long current) {
        return new IllegalStateException("session revision conflict: expected " + expected + ", current " + current);
    }

    private static void requireSamePayload(String commandId, String payloadHash, Journal prior) {
        if (!prior.payloadHash.equals(payloadHash)) {
            throw new JiException(new JiError(ErrorCode.COMMAND_PAYLOAD_CONFLICT, Map.of(
                    "commandId", commandId,
                    "existingPayloadSha256", prior.payloadHash,
                    "suppliedPayloadSha256", payloadHash),
                    Optional.empty(), Optional.empty(), OptionalLong.empty()));
        }
    }

    private static final class State {
        private long acceptedSeq;
        private long eventSeq;
        private long snapshotRevision;
        private long snapshotBaseEventSeq;
        private byte[] snapshotPayload = new byte[0];
        private SessionDocument document;
        private final Map<String, Journal> commands = new LinkedHashMap<>();
        private final List<DurableEvent> events = new ArrayList<>();
    }

    private record TerminalRun(String runId, String outcome) {}

    private record Journal(String payloadHash, String resultRef, long acceptedSeq, Status status, Commit commit) {
        private Journal reserved() { return new Journal(payloadHash, resultRef, acceptedSeq, Status.RESERVED, null); }
        private Journal retryable() { return new Journal(payloadHash, resultRef, acceptedSeq, Status.RETRYABLE, null); }
        private Journal completed(Commit value) {
            return new Journal(payloadHash, resultRef, acceptedSeq, Status.COMPLETED, value);
        }
    }
}

