package io.github.diodeme.ji.host;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.github.diodeme.ji.ai.Content;
import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiError;
import io.github.diodeme.ji.error.JiException;
import io.github.diodeme.ji.session.model.CanonicalSessionState;
import io.github.diodeme.ji.session.tree.SessionDocument;
import io.github.diodeme.ji.session.tree.SessionInputCoordinator;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.OptionalLong;
import java.util.function.UnaryOperator;

/** In-memory reference HostStore. All facts for one Session commit under one lock. */
public final class MemoryHostStore implements HostStore {
    private final Map<String, State> sessions = new LinkedHashMap<>();
    private final ObjectMapper mapper;

    public MemoryHostStore() {
        this(new ObjectMapper());
    }

    MemoryHostStore(ObjectMapper mapper) {
        this.mapper = Objects.requireNonNull(mapper, "mapper");
    }

    @Override
    public synchronized SessionDocument create(
            String sessionId, ModelRef model, String workingDirectory, Instant createdAt) {
        if (sessions.containsKey(sessionId)) throw new IllegalStateException("session already exists: " + sessionId);
        SessionDocument document = SessionDocument.empty(sessionId, model, workingDirectory, createdAt);
        State state = new State(document);
        state.snapshotPayload = encode(document, state.queue, Optional.empty(), Optional.empty());
        sessions.put(sessionId, state);
        return document;
    }

    @Override
    public synchronized Optional<SessionDocument> load(String sessionId) {
        State state = sessions.get(sessionId);
        return state == null ? Optional.empty() : Optional.of(state.document);
    }

    @Override
    public synchronized List<SessionDocument.Metadata> list() {
        return sessions.values().stream().map(state -> state.document.metadata())
                .sorted(Comparator.comparing(SessionDocument.Metadata::createdAt).reversed()).toList();
    }

    @Override
    public synchronized SessionDocument update(
            String sessionId, long expectedRevision, UnaryOperator<SessionDocument> transition) {
        State state = requireSession(sessionId, expectedRevision);
        SessionDocument before = state.document;
        SessionDocument next = transition.apply(before);
        requireSuccessor(before, next);

        FollowUpQueue nextQueue = state.queue;
        Optional<CanonicalSessionState.Run> beforeRun = before.execution().activeRun();
        Optional<CanonicalSessionState.Run> afterRun = next.execution().activeRun();
        if (beforeRun.isPresent() && afterRun.isPresent()
                && beforeRun.orElseThrow().status() != CanonicalSessionState.RunStatus.CANCELLING
                && afterRun.orElseThrow().status() == CanonicalSessionState.RunStatus.CANCELLING
                && !nextQueue.paused()) {
            nextQueue = nextQueue.pause(nextQueue.revision());
        }

        Map<String, Journal> nextCommands = new LinkedHashMap<>(state.commands);
        Optional<String> terminalRunId = next.execution().completedRuns().stream()
                .filter(candidate -> before.execution().completedRuns().stream()
                        .noneMatch(prior -> prior.id().equals(candidate.id())))
                .map(candidate -> candidate.id().value())
                .findFirst();
        Journal terminalJournal = terminalRunId.flatMap(runId -> nextCommands.values().stream()
                .filter(candidate -> candidate.resultRef.equals(runId)
                        && candidate.status == Status.RESERVED && candidate.commit == null)
                .findFirst()).orElse(null);

        Optional<String> terminalOutcome = terminalRunId.flatMap(runId -> next.execution().completedRuns().stream()
                .filter(run -> run.id().value().equals(runId)).findFirst()
                .flatMap(run -> run.outcome().map(Enum::name)));
        if (terminalRunId.isPresent() && terminalJournal == null) {
            throw new IllegalStateException("command.not_reserved");
        }
        PreparedProjection projection = prepareProjection(
                state, "session.snapshot", next, nextQueue, terminalRunId, terminalOutcome);
        if (terminalJournal != null) {
            var commit = new Commit(
                    terminalJournal.acceptedSeq, projection.eventSeq(), projection.snapshotRevision(),
                    terminalJournal.resultRef);
            nextCommands.replaceAll((commandId, candidate) -> candidate == terminalJournal
                    ? candidate.completed(commit) : candidate);
        }

        state.document = next;
        state.queue = nextQueue;
        state.commands = nextCommands;
        applyProjection(state, projection);
        return next;
    }

    @Override
    public synchronized SessionDocument fork(
            String sourceSessionId, String newSessionId, String lane, Optional<String> targetEntryId,
            SessionDocument.ForkPosition position, Instant createdAt, long expectedSourceRevision) {
        if (sessions.containsKey(newSessionId)) throw new IllegalStateException("session already exists: " + newSessionId);
        State source = requireSession(sourceSessionId, expectedSourceRevision);
        SessionDocument fork = source.document.fork(newSessionId, lane, targetEntryId, position, createdAt);
        State state = new State(fork);
        state.snapshotPayload = encode(fork, state.queue, Optional.empty(), Optional.empty());
        sessions.put(newSessionId, state);
        return fork;
    }

    @Override
    public synchronized void delete(String sessionId, long expectedRevision) {
        State state = sessions.get(sessionId);
        if (state == null) return;
        requireRevision(state.document, expectedRevision);
        sessions.remove(sessionId);
    }

    @Override
    public synchronized PromptAcceptance acceptPrompt(
            String sessionId, String commandId, String payloadHash, String resultRef,
            long expectedSessionRevision, String clientId, List<String> content, List<String> attachments) {
        State state = requireSession(sessionId);
        Journal prior = state.commands.get(commandId);
        if (prior != null) {
            requireSamePayload(commandId, payloadHash, prior);
            if (prior.status == Status.RETRYABLE) {
                Journal reserved = prior.reserved();
                state.commands.put(commandId, reserved);
                return new PromptAcceptance(reserved.acceptedSeq, reserved.resultRef,
                        state.queue.revision(), reserved.status, true);
            }
            return new PromptAcceptance(prior.acceptedSeq, prior.resultRef,
                    state.queue.revision(), prior.status, false);
        }
        requireRevision(state.document, expectedSessionRevision);
        long acceptedSeq = Math.incrementExact(state.acceptedSeq);
        boolean queued = state.document.execution().activeRun().isPresent()
                || state.queue.paused()
                || state.commands.values().stream().anyMatch(command -> command.status == Status.RESERVED);
        if (queued) {
            FollowUpQueue.Item item = new FollowUpQueue.Item(
                    commandId, commandId, acceptedSeq, state.queue.items().size(), FollowUpQueue.Kind.FOLLOW_UP,
                    clientId, content, attachments);
            FollowUpQueue nextQueue = state.queue.enqueue(item, state.queue.revision());
            Map<String, Journal> nextCommands = new LinkedHashMap<>(state.commands);
            nextCommands.put(commandId,
                    new Journal(payloadHash, resultRef, acceptedSeq, Status.QUEUED, null));
            PreparedProjection projection = prepareProjection(
                    state, "queue.changed", state.document, nextQueue);
            state.acceptedSeq = acceptedSeq;
            state.queue = nextQueue;
            state.commands = nextCommands;
            applyProjection(state, projection);
            return new PromptAcceptance(acceptedSeq, resultRef, state.queue.revision(), Status.QUEUED, false);
        }
        state.acceptedSeq = acceptedSeq;
        state.commands.put(commandId,
                new Journal(payloadHash, resultRef, acceptedSeq, Status.RESERVED, null));
        return new PromptAcceptance(acceptedSeq, resultRef, state.queue.revision(), Status.RESERVED, true);
    }

    @Override
    public synchronized Optional<ClaimedPrompt> claimNextPrompt(String sessionId) {
        State state = requireSession(sessionId);
        if (state.document.execution().activeRun().isPresent()) return Optional.empty();
        FollowUpQueue.Consumed consumed = state.queue.consumeNext(state.queue.revision());
        if (consumed.item().isEmpty()) return Optional.empty();
        FollowUpQueue.Item item = consumed.item().orElseThrow();
        Journal journal = state.commands.get(item.commandId());
        if (journal == null || journal.status != Status.QUEUED
                || journal.acceptedSeq != item.acceptedSeq()) {
            throw new IllegalStateException("queue item and command journal disagree");
        }
        Map<String, Journal> nextCommands = new LinkedHashMap<>(state.commands);
        nextCommands.put(item.commandId(), journal.reserved());
        PreparedProjection projection = prepareProjection(
                state, "queue.claimed", state.document, consumed.queue());
        state.queue = consumed.queue();
        state.commands = nextCommands;
        applyProjection(state, projection);
        return Optional.of(new ClaimedPrompt(sessionId, item, journal.payloadHash, journal.resultRef));
    }

    @Override
    public synchronized void rollbackClaim(String sessionId, ClaimedPrompt claim) {
        State state = requireSession(sessionId);
        if (!claim.sessionId().equals(sessionId)) throw new IllegalArgumentException("claim belongs to another Session");
        Journal journal = state.commands.get(claim.item().commandId());
        if (journal == null || journal.status != Status.RESERVED
                || journal.acceptedSeq != claim.item().acceptedSeq()
                || !journal.payloadHash.equals(claim.payloadHash())
                || !journal.resultRef.equals(claim.resultRef())) {
            throw new IllegalStateException("claimed prompt and command journal disagree");
        }
        FollowUpQueue nextQueue = state.queue.requeueFront(claim.item(), state.queue.revision());
        Map<String, Journal> nextCommands = new LinkedHashMap<>(state.commands);
        nextCommands.put(claim.item().commandId(), journal.queued());
        PreparedProjection projection = prepareProjection(
                state, "queue.claim_rolled_back", state.document, nextQueue);
        state.queue = nextQueue;
        state.commands = nextCommands;
        applyProjection(state, projection);
    }

    @Override
    public synchronized SessionDocument beginNextTurn(
            String sessionId, long expectedSessionRevision,
            SessionInputCoordinator.OptionalInputTransition transition) {
        State state = requireSession(sessionId, expectedSessionRevision);
        FollowUpQueue.Consumed consumed = state.queue.consumeSteer(state.queue.revision());
        Optional<SessionInputCoordinator.QueuedInput> input = consumed.item().map(MemoryHostStore::queuedInput);
        SessionDocument next;
        try {
            next = transition.apply(state.document, input);
            requireSuccessor(state.document, next);
        } catch (RuntimeException failure) {
            consumed.item().ifPresent(item -> rollbackUninjectedSteer(state, item));
            throw failure;
        }
        if (consumed.item().isPresent()) {
            FollowUpQueue.Item item = consumed.item().orElseThrow();
            Map<String, Journal> nextCommands = injectedCommands(state, item);
            PreparedProjection projection = prepareProjection(
                    state, "queue.steer_injected", next, consumed.queue());
            state.document = next;
            state.queue = consumed.queue();
            state.commands = nextCommands;
            applyProjection(state, projection);
        } else {
            PreparedProjection projection = prepareProjection(
                    state, "session.snapshot", next, consumed.queue());
            state.document = next;
            applyProjection(state, projection);
        }
        return next;
    }

    @Override
    public synchronized Optional<SessionDocument> continueWithSteer(
            String sessionId, long expectedSessionRevision,
            SessionInputCoordinator.RequiredInputTransition transition) {
        State state = requireSession(sessionId, expectedSessionRevision);
        FollowUpQueue.Consumed consumed = state.queue.consumeSteer(state.queue.revision());
        if (consumed.item().isEmpty()) return Optional.empty();
        FollowUpQueue.Item item = consumed.item().orElseThrow();
        SessionDocument next;
        try {
            next = transition.apply(state.document, queuedInput(item));
            requireSuccessor(state.document, next);
        } catch (RuntimeException failure) {
            rollbackUninjectedSteer(state, item);
            throw failure;
        }
        Map<String, Journal> nextCommands = injectedCommands(state, item);
        PreparedProjection projection = prepareProjection(
                state, "queue.steer_injected", next, consumed.queue());
        state.document = next;
        state.queue = consumed.queue();
        state.commands = nextCommands;
        applyProjection(state, projection);
        return Optional.of(next);
    }

    @Override
    public synchronized void release(
            String sessionId, String commandId, String payloadHash, String resultRef) {
        State state = requireSession(sessionId);
        Journal journal = state.commands.get(commandId);
        if (journal == null) throw new IllegalStateException("command.not_found");
        requireSamePayload(commandId, payloadHash, journal);
        if (!journal.resultRef.equals(resultRef)) throw new IllegalStateException("command.result_conflict");
        if (journal.commit != null) throw new IllegalStateException("command.already_completed");
        if (journal.status != Status.RESERVED) throw new IllegalStateException("command.not_reserved");
        state.commands.put(commandId, journal.retryable());
    }

    @Override
    public synchronized Optional<CommandRecord> command(
            String sessionId, String commandId, String payloadHash) {
        State state = sessions.get(sessionId);
        if (state == null) return Optional.empty();
        Journal journal = state.commands.get(commandId);
        if (journal == null) return Optional.empty();
        requireSamePayload(commandId, payloadHash, journal);
        return Optional.of(new CommandRecord(journal.acceptedSeq, journal.resultRef,
                journal.status, Optional.ofNullable(journal.commit)));
    }

    @Override
    public synchronized FollowUpQueue queue(String sessionId) {
        return requireSession(sessionId).queue;
    }

    @Override
    public synchronized FollowUpQueue reorderQueue(
            String sessionId, List<String> itemIds, long expectedQueueRevision) {
        State state = requireSession(sessionId);
        FollowUpQueue nextQueue = state.queue.reorder(itemIds, expectedQueueRevision);
        PreparedProjection projection = prepareProjection(state, "queue.changed", state.document, nextQueue);
        state.queue = nextQueue;
        applyProjection(state, projection);
        return state.queue;
    }

    @Override
    public synchronized FollowUpQueue promote(
            String sessionId, String itemId, long expectedQueueRevision) {
        State state = requireSession(sessionId);
        FollowUpQueue nextQueue = state.queue.promote(itemId, expectedQueueRevision);
        PreparedProjection projection = prepareProjection(state, "queue.changed", state.document, nextQueue);
        state.queue = nextQueue;
        applyProjection(state, projection);
        return state.queue;
    }

    @Override
    public synchronized FollowUpQueue.Removed remove(
            String sessionId, String itemId, String requestingClientId, long expectedQueueRevision) {
        State state = requireSession(sessionId);
        FollowUpQueue.Item prior = state.queue.items().stream()
                .filter(item -> item.itemId().equals(itemId)).findFirst()
                .orElseThrow(() -> new IllegalArgumentException("queue item not found"));
        Journal journal = state.commands.get(prior.commandId());
        if (journal == null || journal.acceptedSeq != prior.acceptedSeq() || journal.status != Status.QUEUED) {
            throw new IllegalStateException("queue item and command journal disagree");
        }
        FollowUpQueue.Removed removed = state.queue.remove(itemId, requestingClientId, expectedQueueRevision);
        Map<String, Journal> nextCommands = new LinkedHashMap<>(state.commands);
        nextCommands.put(prior.commandId(), journal.cancelled());
        PreparedProjection projection = prepareProjection(
                state, "queue.changed", state.document, removed.queue());
        state.queue = removed.queue();
        state.commands = nextCommands;
        applyProjection(state, projection);
        return removed;
    }

    @Override
    public synchronized FollowUpQueue resumeQueue(String sessionId, long expectedQueueRevision) {
        State state = requireSession(sessionId);
        FollowUpQueue nextQueue = state.queue.resume(expectedQueueRevision);
        PreparedProjection projection = prepareProjection(state, "queue.changed", state.document, nextQueue);
        state.queue = nextQueue;
        applyProjection(state, projection);
        return state.queue;
    }

    @Override
    public synchronized Snapshot snapshot(String sessionId) {
        State state = requireSession(sessionId);
        return new Snapshot(state.snapshotRevision, state.snapshotBaseEventSeq, state.snapshotPayload);
    }

    @Override
    public synchronized List<DurableEvent> replay(String sessionId, long afterEventSeq) {
        if (afterEventSeq < 0) throw new IllegalArgumentException("afterEventSeq must be non-negative");
        return requireSession(sessionId).events.stream()
                .filter(event -> event.eventSeq() > afterEventSeq).toList();
    }

    @Override
    public synchronized Optional<Completion> completion(String resultRef) {
        for (State state : sessions.values()) {
            for (Journal journal : state.commands.values()) {
                if (!journal.resultRef.equals(resultRef) || journal.status != Status.COMPLETED
                        || journal.commit == null) continue;
                String outcome = state.document.execution().completedRuns().stream()
                        .filter(run -> run.id().value().equals(resultRef))
                        .flatMap(run -> run.outcome().stream()).map(Enum::name).findFirst()
                        .orElseThrow(() -> new IllegalStateException("completed journal has no terminal Run"));
                return Optional.of(new Completion(journal.commit, outcome));
            }
        }
        return Optional.empty();
    }

    private void rollbackUninjectedSteer(State state, FollowUpQueue.Item item) {
        FollowUpQueue nextQueue = state.queue.rollbackUninjectedSteer(item, state.queue.revision());
        PreparedProjection projection = prepareProjection(
                state, "queue.steer_rolled_back", state.document, nextQueue);
        state.queue = nextQueue;
        applyProjection(state, projection);
    }

    private static Map<String, Journal> injectedCommands(State state, FollowUpQueue.Item item) {
        Journal journal = state.commands.get(item.commandId());
        if (journal == null || journal.status != Status.QUEUED
                || journal.acceptedSeq != item.acceptedSeq()) {
            throw new IllegalStateException("steer and command journal disagree");
        }
        Map<String, Journal> next = new LinkedHashMap<>(state.commands);
        next.put(item.commandId(), journal.injected());
        return next;
    }

    private static SessionInputCoordinator.QueuedInput queuedInput(FollowUpQueue.Item item) {
        return new SessionInputCoordinator.QueuedInput(
                item.itemId(), item.commandId(), item.acceptedSeq(), item.clientId(),
                item.content(), item.attachments());
    }

    private PreparedProjection prepareProjection(
            State state, String eventType, SessionDocument document, FollowUpQueue queue) {
        return prepareProjection(state, eventType, document, queue, Optional.empty(), Optional.empty());
    }

    private PreparedProjection prepareProjection(
            State state, String eventType, SessionDocument document, FollowUpQueue queue,
            Optional<String> runId, Optional<String> outcome) {
        byte[] encoded = encode(document, queue, runId, outcome);
        long eventSeq = Math.incrementExact(state.eventSeq);
        long snapshotRevision = Math.incrementExact(state.snapshotRevision);
        return new PreparedProjection(eventSeq, snapshotRevision, eventType, encoded);
    }

    private static void applyProjection(State state, PreparedProjection projection) {
        long eventSeq = projection.eventSeq();
        long snapshotRevision = projection.snapshotRevision();
        state.eventSeq = eventSeq;
        state.snapshotRevision = snapshotRevision;
        state.snapshotBaseEventSeq = eventSeq;
        state.snapshotPayload = projection.payload();
        state.events.add(new DurableEvent(
                eventSeq, snapshotRevision, projection.eventType(), projection.payload()));
    }

    private byte[] encode(
            SessionDocument document, FollowUpQueue queue,
            Optional<String> runId, Optional<String> outcome) {
        Map<String, Object> value = new LinkedHashMap<>();
        value.put("schemaVersion", 1);
        value.put("sessionId", document.metadata().sessionId());
        value.put("sessionRevision", document.revision());
        runId.ifPresent(id -> value.put("runId", id));
        outcome.ifPresent(result -> value.put("outcome", result.toLowerCase(java.util.Locale.ROOT)));
        value.put("usage", Map.of(
                "inputTokens", document.usage().inputTokens(),
                "outputTokens", document.usage().outputTokens(),
                "cacheReadTokens", document.usage().cacheReadTokens(),
                "cacheWriteTokens", document.usage().cacheWriteTokens(),
                "costMicros", document.usage().costMicros()));
        value.put("transcript", document.snapshot().transcript().stream()
                .map(MemoryHostStore::message).toList());
        value.put("queueRevision", queue.revision());
        value.put("queuePaused", queue.paused());
        value.put("queue", queue.items().stream().map(item -> Map.<String, Object>of(
                "itemId", item.itemId(), "acceptedSeq", item.acceptedSeq(),
                "order", item.order(), "kind", item.kind().name().toLowerCase(java.util.Locale.ROOT),
                "clientId", item.clientId(), "content", item.content(), "attachments", item.attachments()))
                .toList());
        try {
            return mapper.writeValueAsBytes(value);
        } catch (JsonProcessingException exception) {
            throw new IllegalStateException("Host projection is not serializable", exception);
        }
    }

    private static Map<String, Object> message(Message message) {
        Map<String, Object> value = new LinkedHashMap<>();
        value.put("id", message.id());
        value.put("role", message.role().name().toLowerCase(java.util.Locale.ROOT));
        value.put("text", message.text());
        message.toolCallId().ifPresent(id -> value.put("toolCallId", id));
        value.put("toolCalls", message.content().stream()
                .filter(Content.ToolCall.class::isInstance)
                .map(Content.ToolCall.class::cast)
                .map(call -> Map.<String, Object>of(
                        "id", call.id(), "name", call.name(), "arguments", call.arguments()))
                .toList());
        return value;
    }

    private State requireSession(String sessionId, long expectedRevision) {
        State state = requireSession(sessionId);
        requireRevision(state.document, expectedRevision);
        return state;
    }

    private State requireSession(String sessionId) {
        State state = sessions.get(sessionId);
        if (state == null) throw new IllegalStateException("session not found: " + sessionId);
        return state;
    }

    private static void requireRevision(SessionDocument document, long expectedRevision) {
        if (document.revision() != expectedRevision) {
            throw new IllegalStateException("session revision conflict: expected " + expectedRevision
                    + ", current " + document.revision());
        }
    }

    private static void requireSuccessor(SessionDocument before, SessionDocument next) {
        if (next == null || !next.metadata().sessionId().equals(before.metadata().sessionId())
                || next.revision() != Math.incrementExact(before.revision())) {
            throw new IllegalStateException("Session transition must preserve identity and advance revision once");
        }
    }

    private static void requireSamePayload(String commandId, String payloadHash, Journal prior) {
        if (!prior.payloadHash.equals(payloadHash)) {
            throw new JiException(new JiError(ErrorCode.COMMAND_PAYLOAD_CONFLICT, Map.of(
                    "commandId", commandId,
                    "existingPayloadSha256", prior.payloadHash,
                    "suppliedPayloadSha256", payloadHash),
                    Optional.empty(), Optional.empty(), OptionalLong.empty()));
        }
    }

    private static final class State {
        private long acceptedSeq;
        private long eventSeq;
        private long snapshotRevision;
        private long snapshotBaseEventSeq;
        private byte[] snapshotPayload = new byte[0];
        private SessionDocument document;
        private FollowUpQueue queue = FollowUpQueue.empty();
        private Map<String, Journal> commands = new LinkedHashMap<>();
        private final List<DurableEvent> events = new ArrayList<>();

        private State(SessionDocument document) {
            this.document = document;
        }
    }

    private record PreparedProjection(
            long eventSeq, long snapshotRevision, String eventType, byte[] payload) {}

    private record Journal(String payloadHash, String resultRef, long acceptedSeq, Status status, Commit commit) {
        private Journal reserved() {
            return new Journal(payloadHash, resultRef, acceptedSeq, Status.RESERVED, null);
        }
        private Journal retryable() {
            return new Journal(payloadHash, resultRef, acceptedSeq, Status.RETRYABLE, null);
        }
        private Journal queued() {
            return new Journal(payloadHash, resultRef, acceptedSeq, Status.QUEUED, null);
        }
        private Journal injected() {
            return new Journal(payloadHash, resultRef, acceptedSeq, Status.INJECTED, null);
        }
        private Journal completed(Commit value) {
            return new Journal(payloadHash, resultRef, acceptedSeq, Status.COMPLETED, value);
        }
        private Journal cancelled() {
            return new Journal(payloadHash, resultRef, acceptedSeq, Status.CANCELLED, null);
        }
    }
}
